const text = String(params.text || params.input || '').trim();
if (!text) return { error: 'pass params.text' };
const slug = text
  .toLowerCase()
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
return { input: text, slug: slug || 'untitled' };
